export function OpenTickets({tickets,note}:{tickets:readonly Ticket[];note:string}){
  const open=useMemo(()=>tickets.filter(t=>t.status==="OPEN"),[tickets]);
  return <div><p>{note}</p><List items={open}/></div>;
}

